import summary
import unittest
import weights


class TestWeightsAndSummary(unittest.TestCase):
    def test_normalize_representative(self):
        result = weights.normalize([1.0, 3.0])
        self.assertEqual(result, [0.25, 0.75])

    def test_normalize_single_weight(self):
        result = weights.normalize([5.0])
        self.assertEqual(result, [1.0])

    def test_normalize_with_zero_weight(self):
        result = weights.normalize([0.0, 2.0, 0.0])
        self.assertEqual(result, [0.0, 1.0, 0.0])

    def test_normalize_empty_raises_value_error(self):
        with self.assertRaises(ValueError):
            weights.normalize([])

    def test_normalize_negative_weight_raises_value_error(self):
        with self.assertRaises(ValueError):
            weights.normalize([-1.0, 2.0])

    def test_normalize_sum_zero_raises_value_error(self):
        with self.assertRaises(ValueError):
            weights.normalize([0.0, 0.0])

    def test_weighted_mean_representative(self):
        result = summary.weighted_mean([1.0, 2.0, 3.0], [1.0, 1.0, 2.0])
        self.assertAlmostEqual(result, 2.25)

    def test_weighted_mean_single_element(self):
        result = summary.weighted_mean([4.0], [2.0])
        self.assertAlmostEqual(result, 4.0)

    def test_weighted_mean_with_zero_weight(self):
        result = summary.weighted_mean([10.0, 20.0], [0.0, 5.0])
        self.assertAlmostEqual(result, 20.0)

    def test_weighted_mean_different_lengths_raises_value_error(self):
        with self.assertRaises(ValueError):
            summary.weighted_mean([1.0, 2.0], [1.0])

    def test_weighted_mean_different_lengths_longer_weights_raises_value_error(self):
        with self.assertRaises(ValueError):
            summary.weighted_mean([1.0], [1.0, 2.0])


if __name__ == "__main__":
    unittest.main()

