import unittest
import intervals


class TestMergeIntervals(unittest.TestCase):
    def test_empty_input(self):
        result = intervals.merge_intervals([])
        self.assertEqual(result, [])
        self.assertIsInstance(result, list)

    def test_single_interval(self):
        result = intervals.merge_intervals([(1.0, 3.0)])
        self.assertEqual(result, [(1.0, 3.0)])

    def test_disjoint_non_overlapping_intervals(self):
        result = intervals.merge_intervals([(1.0, 2.0), (4.0, 5.0)])
        self.assertEqual(result, [(1.0, 2.0), (4.0, 5.0)])

    def test_overlapping_intervals(self):
        result = intervals.merge_intervals([(1.0, 4.0), (2.0, 6.0)])
        self.assertEqual(result, [(1.0, 6.0)])

    def test_touching_intervals(self):
        result = intervals.merge_intervals([(1.0, 3.0), (3.0, 5.0)])
        self.assertEqual(result, [(1.0, 5.0)])

    def test_nested_contained_intervals(self):
        result = intervals.merge_intervals([(1.0, 8.0), (2.0, 5.0)])
        self.assertEqual(result, [(1.0, 8.0)])

    def test_arbitrary_input_order_sorted_by_start(self):
        result = intervals.merge_intervals([(7.0, 8.0), (1.0, 3.0), (2.0, 5.0)])
        self.assertEqual(result, [(1.0, 5.0), (7.0, 8.0)])

    def test_closed_point_intervals(self):
        result = intervals.merge_intervals([(1.0, 1.0), (1.0, 2.0), (4.0, 4.0)])
        self.assertEqual(result, [(1.0, 2.0), (4.0, 4.0)])

    def test_negative_and_float_coordinates(self):
        result = intervals.merge_intervals([(-5.5, -2.0), (-3.0, 1.5)])
        self.assertEqual(result, [(-5.5, 1.5)])

    def test_chain_of_multiple_touching_and_overlapping(self):
        result = intervals.merge_intervals([(1.0, 2.0), (2.0, 3.5), (3.0, 5.0)])
        self.assertEqual(result, [(1.0, 5.0)])

    def test_returns_new_list_and_tuples(self):
        inp = [(1.0, 2.0)]
        result = intervals.merge_intervals(inp)
        self.assertIsNot(result, inp)
        self.assertIsInstance(result, list)
        self.assertIsInstance(result[0], tuple)

    def test_input_not_modified(self):
        inp = [(5.0, 6.0), (1.0, 3.0)]
        intervals.merge_intervals(inp)
        self.assertEqual(inp, [(5.0, 6.0), (1.0, 3.0)])

    def test_value_error_when_start_greater_than_end(self):
        with self.assertRaises(ValueError):
            intervals.merge_intervals([(4.0, 2.0)])

    def test_value_error_when_any_interval_has_start_greater_than_end(self):
        with self.assertRaises(ValueError):
            intervals.merge_intervals([(1.0, 3.0), (5.0, 2.0), (6.0, 8.0)])


